function showForm(title,fields,submit){$('dialogTitle').textContent=title;$('dialogError').textContent='';$('dialogFields').replaceChildren();const data={};for(const f of fields){data[f.key]=f.value??'';const input=field($('dialogFields'),f.label,f.value,v=>data[f.key]=v,f);input.dataset.key=f.key;}dialogSubmit=()=>{for(const input of $('dialogFields').querySelectorAll('[data-key]'))data[input.dataset.key]=input.type==='number'?Number(input.value):input.value;return submit(data);};$('formDialog').showModal();}
$('dialogForm').onsubmit=async e=>{e.preventDefault();try{await dialogSubmit();$('formDialog').close();}catch(e){$('dialogError').textContent=e.message;}};$('closeDialog').onclick=()=>$('formDialog').close();
$('newProject').onclick=()=>showForm('Neues CAD-Projekt',[{key:'name',label:'Projektname',value:''},{key:'order',label:'Auftragsnummer'},{key:'customer',label:'Kunde'},{key:'address',label:'Objektadresse'}],async data=>{if(!data.name.trim())throw Error('Bitte einen Projektnamen eingeben.');const d=addStandardPages({...project(data.name),...data});await database('save',d);docs.push(d);open(d);});
$('demoProject').onclick=async()=>{try{const d=demo();await database('save',d);docs.push(d);open(d);}catch(e){toast(e.message)}};
$('projectSettings').onclick=()=>showForm('Projektdaten',['name','order','schema','customer','address','author','date','ratedCurrent'].map((key,i)=>({key,label:['Projektname','Auftrag','Schemanummer','Kunde','Objektadresse','Gezeichnet von','Datum','Bemessungsstrom (z. B. 100 A)'][i],value:doc[key],type:key==='date'?'date':'text'})),data=>{if(!data.name.trim())throw Error('Bitte einen Projektnamen eingeben.');change(()=>Object.assign(doc,data));});
$('projectSearch').oninput=home;
$('projectList').onclick=async e=>{const button=e.target.closest('button');if(!button)return;const id=button.dataset.open||button.dataset.remove,d=docs.find(d=>d.id===id);if(!d)return;if(button.dataset.open)open(d);else if(confirm(`Projekt «${d.name}» auf diesem Gerät löschen?`)){try{await database('delete',id);docs=docs.filter(d=>d.id!==id);home();}catch(e){toast(e.message)}}};
$('backHome').onclick=async()=>{await flush();doc=null;wire=null;$('editor').hidden=true;$('cadHome').hidden=false;home();};
$('backupProject').onclick=()=>download(new Blob([JSON.stringify(doc,null,2)],{type:'application/json'}),`${doc.order||doc.name} - CAD.json`);
$('importProject').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>20*1024*1024)throw Error('Projektdatei zu gross (max. 20 MB).');const d=validateProject(JSON.parse(await f.text()));d.id=uid();d.name+=' (Import)';await database('save',d);docs.push(d);open(d);}catch(e){toast(e.message)}finally{$('importProject').value=''}};
$('addPage').onclick=()=>showForm('Seite hinzufügen',[{key:'title',label:'Seitentitel',value:'Neue Seite'},{key:'type',label:'Seitentyp',value:'schema',options:[['schema','Elektroschema'],['dispo','Disposition'],['cover','Deckblatt'],['index','Inhaltsverzeichnis']]},{key:'number',label:'Blattnummer',value:Math.max(...doc.pages.map(p=>p.number))+1,type:'number',min:1,max:9999},{key:'inherit',label:'Sammelschienen übernehmen von',value:current().type==='schema'?current().id:'',options:[['','Keine Übernahme'],...doc.pages.filter(p=>p.type==='schema').map(p=>[p.id,`Blatt ${p.number} · ${p.title}`])]}],data=>{if(doc.pages.length>=200)throw Error('Maximal 200 Seiten pro Projekt.');if(!data.title.trim()||!Number.isInteger(data.number)||doc.pages.some(p=>p.number===data.number))throw Error('Titel und eindeutige ganze Blattnummer erforderlich.');change(()=>{const p=page(data.type,data.number);p.title=data.title;doc.pages.push(p);if(data.type==='schema'&&data.inherit)inheritBus(doc,doc.pages.find(q=>q.id===data.inherit),p);pageId=p.id;selected=null;multi=[];wire=null;});});
$('pageList').onclick=e=>{const b=e.target.closest('[data-page]');if(b){pageId=b.dataset.page;hoverPoint=null;selected=null;multi=[];wire=null;render();}};
$('copyPage').onclick=()=>{if(doc.pages.length>=200)return toast('Maximal 200 Seiten pro Projekt.');change(()=>{const q=duplicatePage(doc,current());doc.pages.splice(doc.pages.indexOf(current())+1,0,q);pageId=q.id;selected=null;multi=[];wire=null;});};
$('deletePage').onclick=()=>{if(doc.pages.length>1&&confirm('Diese Seite mit allen Elementen entfernen?'))change(()=>{doc.pages=doc.pages.filter(p=>p.id!==pageId);pageId=doc.pages[0].id;selected=null;multi=[];wire=null;});};
function movePage(delta){const i=doc.pages.indexOf(current()),j=i+delta;if(j<0||j>=doc.pages.length)return;change(()=>[doc.pages[i],doc.pages[j]]=[doc.pages[j],doc.pages[i]]);}
$('movePageUp').onclick=()=>movePage(-1);$('movePageDown').onclick=()=>movePage(1);
function symbolList(){
 const q=$('symbolSearch').value,previous=$('symbolGroup').value;
 const originals=templateCatalog?.items||[];
 const groups=[...new Set([...Object.values(symbols).filter(s=>s.group!=='Vorlagen').map(s=>s.group),...originals.map(t=>t.group)])].sort((a,b)=>a.localeCompare(b,'de'));
 $('symbolGroup').innerHTML='<option value="">Alle Gruppen</option>'+groups.map(g=>`<option value="${esc(g)}">${esc(libraryName(g))}</option>`).join('');$('symbolGroup').value=groups.includes(previous)?previous:'';
 const group=$('symbolGroup').value;
 const basic=filterLibrary(Object.entries(symbols).filter(([k])=>k!=='template').map(([kind,s])=>({...s,id:kind,kind,source:'Grundsymbol'})),{query:q,group});
 const imported=filterLibrary(originals,{query:q,group});
 const items=[...basic,...imported],shown=items.slice(0,symbolLimit);
 $('symbolStatus').textContent=`${items.length} Einträge · ${Math.min(items.length,symbolLimit)} angezeigt${templateCatalog?'':' · Originalbibliothek wird geladen …'}`;
 $('symbolList').innerHTML=shown.map(t=>t.kind?`<button class="symbol-card" data-symbol="${t.kind}"><span class="symbol-picture"><svg viewBox="-10 -5 ${t.w+20} ${t.h+10}" fill="none" stroke="currentColor" stroke-width="2">${glyph(t.kind)||'<rect x="2" y="2" width="32" height="40"/>'}</svg></span><strong>${esc(t.name)}</strong><small>Grundsymbol · ${esc(t.group)}</small></button>`:`<button class="symbol-card" data-template="${esc(t.id)}"><span class="symbol-picture"><img src="data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27/%3E" data-preview-id="${esc(t.id)}" loading="lazy" alt="${esc(t.name)}"></span><strong>${esc(libraryName(t.name))}</strong><small>${esc(t.category)} · ${esc(libraryName(t.group))}</small></button>`).join('')||'<p class="hint">Keine Treffer. Suchbegriff oder Gruppe ändern.</p>';
 $('moreSymbols').hidden=items.length<=symbolLimit;
}


async function loadTemplates(){if(templateCatalog){renderTemplates();symbolList();return;}$('templateStatus').textContent='Vorlagen werden geladen …';try{const r=await fetch('cad/templates/catalog.json?v=20261113-13');if(!r.ok)throw Error('Vorlagenbibliothek nicht erreichbar');templateCatalog=await r.json();renderTemplates();symbolList();}catch(e){$('templateStatus').textContent=e.message;$('symbolStatus').textContent=e.message;}}
function renderTemplates(){
 const category=$('templateCategory').value,previous=$('templateGroup').value;
 const groups=[...new Set(templateCatalog.items.filter(t=>!category||t.category===category).map(t=>t.group))].sort((a,b)=>libraryName(a).localeCompare(libraryName(b),'de'));
 $('templateGroup').innerHTML='<option value="">Alle Gruppen</option>'+groups.map(g=>`<option value="${esc(g)}">${esc(libraryName(g))}</option>`).join('');$('templateGroup').value=groups.includes(previous)?previous:'';
 const items=filterLibrary(templateCatalog.items,{query:$('templateSearch').value,category,group:$('templateGroup').value,scope:libraryScope,...librarySettings});
 $('templateStatus').textContent=`${items.length} Vorlagen · ${Math.min(items.length,templateLimit)} angezeigt`;
 $('templateList').innerHTML=items.slice(0,templateLimit).map(t=>`<div class="template-tile"><button class="favorite-toggle" data-favorite="${esc(t.id)}" aria-label="${esc(t.name)} als Favorit" aria-pressed="${librarySettings.favorites.includes(t.id)}" title="Favorit merken">${librarySettings.favorites.includes(t.id)?'★':'☆'}</button><button class="template-card ${activeTemplate?.id===t.id?'active':''}" data-template="${esc(t.id)}" title="${esc(t.name)}"><span class="template-picture"><img src="data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27/%3E" data-preview-id="${esc(t.id)}" loading="lazy" alt="Vorschau ${esc(t.name)}"></span><strong>${esc(libraryName(t.name))}</strong><small>${esc(libraryName(t.group))} · ${t.width} × ${t.height} mm</small><span class="template-badge">${t.supplyPorts?'↳ Sammelschienen · ':''}${t.liveLabels?'Autom. Kennzeichen':esc(t.category)}</span></button></div>`).join('')||`<div class="library-empty"><strong>${libraryScope==='favorites'?'Noch keine passenden Favoriten':libraryScope==='recent'?'Noch keine passenden Vorlagen verwendet':'Keine passende Vorlage'}</strong><p>${libraryScope==='favorites'?'Mit ☆ auf einer Vorlage legst du sie hier ab.':'Suche oder Filter ändern. Unter «Alle» findest du die gesamte Bibliothek.'}</p><button id="resetLibrary">Alle Vorlagen anzeigen</button></div>`;
 $('moreTemplates').hidden=items.length<=templateLimit;
 $('resetLibrary')?.addEventListener('click',()=>{$('templateSearch').value='';$('templateCategory').value='';$('templateGroup').value='';setLibraryScope('all');});
}
function setLibraryScope(scope){libraryScope=scope;templateLimit=40;document.querySelectorAll('[data-scope]').forEach(b=>{b.classList.toggle('active',b.dataset.scope===scope);b.setAttribute('aria-pressed',b.dataset.scope===scope);});if(templateCatalog)renderTemplates();}
document.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>setLibraryScope(b.dataset.scope));
$('templateSearch').oninput=$('templateCategory').onchange=$('templateGroup').onchange=()=>{templateLimit=40;if(templateCatalog)renderTemplates();};$('moreTemplates').onclick=()=>{templateLimit+=40;renderTemplates();};
$('templateList').onclick=async event=>{const favorite=event.target.closest('[data-favorite]');if(favorite){const id=favorite.dataset.favorite;librarySettings.favorites=librarySettings.favorites.includes(id)?librarySettings.favorites.filter(x=>x!==id):[...librarySettings.favorites,id];saveLibrarySettings();renderTemplates();return;}const b=event.target.closest('[data-template]');if(!b)return;const request=++templateRequest;b.disabled=true;try{const r=await fetch(`cad/templates/${b.dataset.template}.json?v=20261112-13`);if(!r.ok)throw Error('Vorlage nicht erreichbar');const template=validateTemplate(await r.json());await loadDetails();if(templateDetails[template.id])template.details=templateDetails[template.id];if(request!==templateRequest)return;activeTemplate=template;setTool('template');$('templateSelected').textContent=template.name;renderTemplates();$('templatePreview').innerHTML=templateMarkup(template,Math.min(170/template.width,120/template.height)*template.width,Math.min(170/template.width,120/template.height)*template.height);toast('Vorlage gewählt – auf dem Blatt platzieren. R dreht die Vorschau.');document.querySelector('.drawing-layout').classList.remove('show-left');}catch(e){toast(e.message)}finally{b.disabled=false;}};

$('symbolSearch').oninput=$('symbolGroup').onchange=()=>{symbolLimit=60;symbolList();};$('moreSymbols').onclick=()=>{symbolLimit+=60;symbolList();};$('symbolList').onclick=e=>{if(e.target.closest('[data-template]')){$('templateList').onclick(e);return;}const b=e.target.closest('[data-symbol]');if(b){setTool(b.dataset.symbol);document.querySelector('.drawing-layout').classList.remove('show-left');}};
document.querySelectorAll('[data-left]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-left]').forEach(x=>x.classList.toggle('active',x===b));$('pagesPanel').hidden=b.dataset.left!=='pages';$('symbolsPanel').hidden=b.dataset.left!=='symbols';$('templatesPanel').hidden=b.dataset.left!=='templates';if(['templates','symbols'].includes(b.dataset.left))loadTemplates();});
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));
$('toggleLeft').onclick=()=>document.querySelector('.drawing-layout').classList.toggle('show-left');$('toggleRight').onclick=()=>document.querySelector('.drawing-layout').classList.toggle('show-right');
$('fit').onclick=fit;$('zoomIn').onclick=()=>zoomBy(1.2);$('zoomOut').onclick=()=>zoomBy(1/1.2);$('undo').onclick=()=>history('undo');$('redo').onclick=()=>history('redo');
function deleteSelected(){if(multi.length){change(()=>{deleteSelection(current(),multi,uid);multi=[];selected=null;});return;}if(!selected)return;change(()=>{const p=current();removeElement(p,selected);removeWire(p,selected);selected=null;multi=[];});}
function duplicateSelected(){if(multi.length>1||multi.some(s=>['line','text'].includes(s.kind)))return toast('Zum Duplizieren ein ganzes Element auswählen.');const p=current(),e=p.elements.find(e=>e.id===selected),w=p.wires.find(w=>w.id===selected);if(!e&&!w)return;change(()=>{if(e){const c=clone(e),fresh=createElement(p,e.kind,e.x+20,e.y+20);Object.assign(c,{id:fresh.id,x:fresh.x,y:fresh.y,tag:fresh.tag});p.elements.push(c);selected=c.id;}else{const c=clone(w);c.id=uid();c.points=wirePoints(p,w).map(pt=>({x:pt.x+20,y:pt.y+20}));c.from=c.to=null;p.wires.push(c);selected=c.id;}});}
function rotate(){if(multi.length>1||multi.some(s=>['line','text'].includes(s.kind)))return toast('Zum Drehen ein ganzes Element auswählen.');if(symbols[tool]){placementRotation=(placementRotation+90)%360;drawPlacement();return;}const e=current().elements.find(e=>e.id===selected);if(e)change(()=>e.rotation=(e.rotation+90)%360);}
$('deleteElement').onclick=deleteSelected;$('duplicateElement').onclick=duplicateSelected;$('rotate').onclick=rotate;
function point(event){const rect=$('paper').getBoundingClientRect();return {x:snap((event.clientX-rect.left)/zoom,$('snap').checked),y:snap((event.clientY-rect.top)/zoom,$('snap').checked)};}
function nearest(pt,excludeWire=null){let best=null,dist=10/zoom;const page=current();const consider=(q,ref)=>{const n=Math.hypot(q.x-pt.x,q.y-pt.y);if(n<dist&&(!excludeWire||canLinkWire(page,excludeWire,ref))){dist=n;best={x:q.x,y:q.y,ref};}};
 for(const e of page.elements){for(const port of ports(e,page))consider(port,{element:e.id,index:port.index});if(e.template){const [w,h]=size(e,page);for(const line of templateLines(e.template)){const pts=linePoints(e,page,line);[line.a,line.b].forEach((q,i)=>consider(pts[i],{element:e.id,local:{x:q.x/e.template.viewWidth,y:q.y/e.template.viewHeight}}));}}}
 for(const q of page.connectionPoints||[])consider(q,{connection:q.id});
 for(const w of page.wires){if(w.id===excludeWire)continue;const pts=wirePoints(page,w);consider(pts[0],{wire:w.id,index:0});consider(pts.at(-1),{wire:w.id,index:1});}return best;
}
function wirePreview(hover){const svg=$('paper').querySelector('svg');svg?.querySelector('#wirePreview')?.remove();if(!wire)return;const pts=[...wire.points,...(hover?[hover]:[])];if(pts.length<2)return;const poly=document.createElementNS('http://www.w3.org/2000/svg','polyline');poly.id='wirePreview';poly.setAttribute('points',wirePoints(current(),{...wire,points:pts}).map(p=>p.x+','+p.y).join(' '));poly.setAttribute('fill','none');poly.setAttribute('stroke','#2463eb');poly.setAttribute('stroke-width','2');poly.setAttribute('stroke-dasharray','5 3');poly.setAttribute('pointer-events','none');svg.append(poly);}
function finishWire(){if(!wire||wire.points.length<2)return toast('Mindestens zwei Punkte für eine Verbindung setzen.');const w=clone(wire);change(()=>{current().wires.push(w);wire=null;selected=w.id;});}
$('finishWire').onclick=finishWire;$('cancelWire').onclick=()=>{wire=null;drawPaper();};
$('paper').onpointerdown=event=>{if(event.button!==0||tool==='pan')return;const p=current(),pt=point(event);if(pt.x<25||pt.x>1175||pt.y<35||pt.y>DRAW.bottom)return;
 const autoPort=event.target.closest('[data-auto-port]');if(tool==='select'&&autoPort){const [id,index]=autoPort.dataset.autoPort.split(':');selected=id;drag={autoPort:Number(index),id,before:clone(doc),moved:false};textClicks.reset();event.preventDefault();$('paper').setPointerCapture(event.pointerId);return;}
 const connection=event.target.closest('[data-connection]');if(tool==='select'&&connection){textClicks.reset();event.preventDefault();showConnection(JSON.parse(connection.dataset.connection));return;}
 if(tool==='select'&&!event.target.closest('[data-wire-handle]')){startSelection(event,pt);return;}
 const handle=event.target.closest('[data-wire-handle]');if(tool==='select'&&handle){const [id,index]=handle.dataset.wireHandle.split(':');const w=p.wires.find(w=>w.id===id);selected=id;drag={wire:id,handle:Number(index),start:pt,before:clone(doc),moved:false};$('paper').setPointerCapture(event.pointerId);return;}
 if(tool==='wire'){if(p.elements.length+p.wires.length>=5000)return toast('Maximal 5000 Elemente pro Seite.');event.preventDefault();if(wire?.points.length>=199)return toast('Verbindung abschliessen: maximal 200 Punkte.');const port=nearest(pt),pos=port?{x:port.x,y:port.y}:pt;if(!wire)wire={id:uid(),points:[pos],from:port?port.ref:null,to:null,dashed:false,label:''};else{if(Math.hypot(pos.x-wire.points.at(-1).x,pos.y-wire.points.at(-1).y)<.1)return;wire.points.push(pos);if(port){wire.to=port.ref;finishWire();return;}}drawPaper();return;}
 if(tool!=='select'){if(p.elements.length+p.wires.length>=5000)return toast('Maximal 5000 Elemente pro Seite.');change(()=>{const e=placement(p,tool,pt,$('snap').checked,placementRotation,activeTemplate,$('autoConnect').checked);if(e){p.elements.push(clone(e));if(e.template){librarySettings.recent=rememberTemplate(librarySettings.recent,e.template.id);saveLibrarySettings();if(templateCatalog)renderTemplates();}selected=e.id;hoverPoint=null;}else toast('Vorlage passt hier nicht in den Zeichenbereich. Drehung oder Abmessungen prüfen.');});return;}
 const target=event.target.closest('[data-element]'),wireTarget=event.target.closest('[data-wire]');selected=target?.dataset.element||wireTarget?.dataset.wire||null;if(wireTarget&&!target){const w=p.wires.find(w=>w.id===selected);drag={wire:w.id,start:pt,points:wirePoints(p,w).map(q=>({x:q.x,y:q.y})),before:clone(doc),moved:false};$('paper').setPointerCapture(event.pointerId);}if(target){const e=p.elements.find(e=>e.id===selected);drag={id:e.id,start:pt,x:e.x,y:e.y,before:clone(doc),moved:false};$('paper').setPointerCapture(event.pointerId);}render();};
$('paper').onpointermove=event=>{if(navigation.isPanning()||tool==='pan')return;const pt=point(event);hoverPoint=pt;$('cursorPosition').textContent=`Pfad ${pathAt(pt.x)} · X ${Math.round(pt.x)} · Y ${Math.round(pt.y)}`;if(drag?.autoPort!==undefined){const phase=Object.keys(BUS).find(k=>Math.abs(BUS[k]-pt.y)<7);if(phase){const e=current().elements.find(e=>e.id===drag.id);e.autoPhases??={};e.autoPhases[drag.autoPort]=phase;drag.moved=true;drawPaper();}return;}if(drag?.marquee){drag.end=pt;drawPaper();return;}if(drag?.multiple){const dx=pt.x-drag.last.x,dy=pt.y-drag.last.y;if(dx||dy){if(!drag.moved){try{multi=materializeLines(current(),multi,uid);}catch(error){endDrag(true);toast(error.message);return;}}moveSelection(current(),multi,dx,dy);drag.last=pt;drag.moved=true;syncSelection();drawPaper();}return;}if(drag?.wire){const w=current().wires.find(w=>w.id===drag.wire);if(drag.handle!==undefined){const i=drag.handle===0?0:w.points.length-1,ref=drag.handle===0?'from':'to',hit=nearest(pt,w.id);w.points[i]=hit?{x:hit.x,y:hit.y}:{x:pt.x,y:pt.y};w[ref]=hit?.ref||null;}else{w.points=drag.points.map(q=>({x:q.x+pt.x-drag.start.x,y:q.y+pt.y-drag.start.y}));w.from=w.to=null;}drag.moved=true;drawPaper();}else if(drag){const e=current().elements.find(e=>e.id===drag.id);e.x=Math.max(30,Math.min(1140,drag.x+pt.x-drag.start.x));e.y=Math.max(40,Math.min(DRAW.bottom,drag.y+pt.y-drag.start.y));if(e.kind==='template'){const [w,h]=size(e,current()),b=bounds(e,w,h);e.x+=Math.max(0,DRAW.left-b.left)-Math.max(0,b.right-DRAW.right);e.y+=Math.max(0,DRAW.top-b.top)-Math.max(0,b.bottom-DRAW.bottom);}if(e.x!==drag.x||e.y!==drag.y)drag.moved=true;drawPaper();}else if(wire)wirePreview(nearest(pt)||pt);else drawPlacement();};
function endDrag(cancel=false){if(!drag)return;if(drag.marquee){if(cancel)multi=drag.previous;else{const added=selectRectangle(current(),drag.start,drag.end,lineMode);multi=[...new Map([...drag.base,...added].map(s=>[selectionKey(s),s])).values()];}drag=null;syncSelection();render();return;}if(drag.multiple){if(cancel){doc=drag.before;multi=drag.previous;}else if(drag.moved){try{swapDispoDrop(current(),drag.before.pages.find(p=>p.id===pageId),multi);if(current().type==='schema'&&multi.length===1&&multi[0].kind==='element'){const e=current().elements.find(e=>e.id===multi[0].id);if(e)alignMacro(e,current(),80);}}catch(error){doc=drag.before;drag=null;toast(error.message);render();return;}undo.push(drag.before);if(undo.length>60)undo.shift();redo=[];save();}drag=null;syncSelection();render();return;}if(cancel){doc=drag.before;}else if(drag.moved){if(!drag.wire&&drag.autoPort===undefined&&$('autoConnect').checked){const e=current().elements.find(e=>e.id===selected);if(e)alignMacro(e,current());}undo.push(drag.before);if(undo.length>60)undo.shift();redo=[];save();}drag=null;render();}
function finishSelectionPointer(event){
 const pending=drag,hit=pending?.clickHit;
 const e=hit?current().elements.find(e=>e.id===hit.id):null;
 const editable=tool==='select'&&(hit?.kind==='text'||hit?.kind==='element'&&e?.kind==='text');
 const key=editable?JSON.stringify([pageId,hit.kind,hit.id,hit.key]):'';
 const moved=!pending||pending.moved||Math.hypot(event.clientX-pending.clickX,event.clientY-pending.clickY)>6;
 endDrag();
 if(!textClicks.tap({key,x:event.clientX,y:event.clientY,time:event.timeStamp,moved,modified:event.ctrlKey||event.metaKey||event.shiftKey}))return;
 if(hit.kind==='text')editTemplateText(e,hit.key);
 else showForm('Text bearbeiten',[{key:'text',label:'Text',type:'textarea',value:e.text}],data=>change(()=>e.text=data.text));
}
$('paper').onpointerup=finishSelectionPointer;
$('paper').onpointercancel=()=>{textClicks.reset();endDrag(true);};
document.addEventListener('keydown',e=>{if(!doc||e.target.closest('input,textarea,select,[contenteditable],dialog'))return;const ctrl=e.ctrlKey||e.metaKey;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&multi.length){e.preventDefault();const delta=arrowStep(current(),e.key,e.shiftKey,e.altKey);change(()=>{multi=materializeLines(current(),multi,uid);moveSelection(current(),multi,delta.dx,delta.dy);syncSelection();});}else if(ctrl&&e.key.toLowerCase()==='a'){e.preventDefault();multi=selectable(current(),false);syncSelection();render();}else if(ctrl&&e.key.toLowerCase()==='z'){e.preventDefault();history(e.shiftKey?'redo':'undo');}else if(ctrl&&e.key.toLowerCase()==='y'){e.preventDefault();history('redo');}else if(ctrl&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateSelected();}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();}else if(e.key==='Escape'){textClicks.reset();if(drag)endDrag(true);multi=[];wire=null;tool='select';selected=null;multi=[];render();}else if(e.key==='Enter'&&wire){e.preventDefault();finishWire();}else if(e.key.toLowerCase()==='f'){e.preventDefault();fit();}else if(e.key.toLowerCase()==='v')setTool('select');else if(e.key.toLowerCase()==='w')setTool('wire');else if(e.key.toLowerCase()==='r')rotate();});
$('help').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();
$('exportSvg').onclick=()=>download(new Blob([svgPage(doc,current())],{type:'image/svg+xml'}),`${doc.order||doc.name} - Blatt ${current().number}.svg`);
$('exportPdf').onclick=async()=>{const b=$('exportPdf');b.disabled=true;try{const snapshot=clone(doc);download(await pdf(snapshot,(n,total)=>b.textContent=`PDF ${n} / ${total}`),`${snapshot.order||snapshot.name} - Schema und Dispo.pdf`);toast('PDF erstellt. Download gestartet.');}catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='PDF herunterladen';}};
window.addEventListener('pagehide',()=>{if(doc){clearTimeout(saveTimer);enqueueSave(clone(doc));}});
symbolList();database('list').then(result=>{docs=result;home();}).catch(e=>{toast('Projekte konnten nicht geladen werden: '+e.message);home();});

// User-controlled width, persisted independently of project data.
const layout=document.querySelector('.drawing-layout'),splitter=$('librarySplitter');
function libraryWidth(value){const max=Math.max(220,Math.min(900,layout.clientWidth-480)),width=Math.max(220,Math.min(max,value));layout.style.setProperty('--library-width',width+'px');splitter.setAttribute('aria-valuenow',Math.round(width));splitter.setAttribute('aria-valuemax',Math.round(max));return width;}
let resizing=false;
try{libraryWidth(Number(localStorage.getItem('cad-library-width'))||320);}catch{libraryWidth(320);}
splitter.onpointerdown=e=>{if(e.button!==0)return;resizing=true;splitter.setPointerCapture(e.pointerId);e.preventDefault();};
splitter.onpointermove=e=>{if(resizing)libraryWidth(e.clientX-layout.getBoundingClientRect().left);};
function endResize(){if(!resizing)return;resizing=false;try{localStorage.setItem('cad-library-width',parseFloat(layout.style.getPropertyValue('--library-width')));}catch{}fit();}
splitter.onpointerup=splitter.onpointercancel=endResize;
splitter.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const current=parseFloat(layout.style.getPropertyValue('--library-width'))||320;libraryWidth(e.key==='Home'?220:e.key==='End'?900:current+(e.key==='ArrowRight'?40:-40));resizing=true;endResize();};
window.addEventListener('resize',()=>{if(doc)libraryWidth(parseFloat(layout.style.getPropertyValue('--library-width'))||320);});

// Keep drawing, editing and view controls separate without changing the active tool.
document.querySelectorAll('[data-ribbon]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-ribbon]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});document.querySelectorAll('[data-ribbon-panel]').forEach(x=>x.hidden=x.dataset.ribbonPanel!==b.dataset.ribbon);});
$('focusDrawing').onclick=()=>{const active=document.querySelector('.drawing-layout').classList.toggle('focus-drawing');$('focusDrawing').setAttribute('aria-pressed',active);$('focusDrawing').textContent=active?'Seitenbereiche anzeigen':'Zeichenfläche vergrössern';requestAnimationFrame(fit);};
$('showProperties').onclick=()=>{const hidden=document.querySelector('.drawing-layout').classList.toggle('hide-properties');$('showProperties').setAttribute('aria-pressed',!hidden);requestAnimationFrame(fit);};
const navigation=installNavigation({viewport:$('viewport'),paper:$('paper'),getZoom:()=>zoom,setZoom:value=>{zoom=value;drawPaper();},isBusy:()=>Boolean(drag),isPanTool:()=>tool==='pan',afterZoom:()=>{hoverPoint=null;$('paper').querySelector('#placementPreview')?.remove();}});
$('actualZoom').onclick=()=>navigation.zoomAt(1);

$('editTemplateLines').onclick=()=>{multi=[];selected=null;lineMode=!lineMode;tool='select';wire=null;$('editTemplateLines').setAttribute('aria-pressed',!lineMode);render();toast(lineMode?'Einzelne Linien und Texte direkt anklicken.':'Gruppenauswahl: Ganze Vorlage auswählen und verschieben.');};

$('contactDemo').onclick=async()=>{try{const d=contactDemo();await database('save',d);docs.push(d);open(d);}catch(e){toast(e.message);}};

$('autoDispo').onclick=async()=>{const target=current(),sourceDoc=doc,button=$('autoDispo');if(button.disabled)return;button.disabled=true;try{await loadDetails();sourceDoc.pages.forEach(p=>p.elements.forEach(attachDetails));const result=await editAutomaticDispo(sourceDoc,target,g=>{if(doc!==sourceDoc)throw Error('Projekt gewechselt – Dispo nicht verändert.');change(()=>{for(const e of [...target.elements])if(e.generatedDispo)removeElement(target,e.id);target.elements.push(...g.elements);target.scale=g.scale;target.dispoConfig=g.config;target.grid=false;selected=null;multi=[];});});toast(result.warnings.length?result.warnings.join(' '):'Dispo automatisch aus Originalvorlagen erstellt.');}catch(e){toast(e.message);}finally{button.disabled=false;}};
$('view3D').onclick=()=>{try{openDispo3D(current(),id=>{selected=id;multi=[{kind:'element',id}];render();});}catch(e){toast(e.message);}};

$('frameDemo').onclick=async()=>{try{const d=drahtwerkDemo(project('Beispiel · Drahtwerk-Aufbau'));await database('save',d);docs.push(d);open(d);pageId=d.pages.find(p=>p.type==='dispo').id;render();}catch(e){toast(e.message);}};

const previewCache=new Map();
const previewObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;const img=entry.target,id=img.dataset.previewId;previewObserver.unobserve(img);if(!previewCache.has(id))previewCache.set(id,fetch(`cad/templates/${encodeURIComponent(id)}.json?v=20261113-13`).then(r=>{if(!r.ok)throw Error('Vorschau fehlt');return r.json();}).then(validateTemplate).then(t=>'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200">${templateMarkup(t,200*t.width/Math.max(t.width,t.height),200*t.height/Math.max(t.width,t.height))}</svg>`)));previewCache.get(id).then(src=>img.src=src).catch(()=>img.alt='Vorschau nicht verfügbar');}});
new MutationObserver(()=>{for(const img of document.querySelectorAll('img[data-preview-id]:not([data-observed])')){img.dataset.observed='1';previewObserver.observe(img);}}).observe(document.body,{childList:true,subtree:true});

const breakerButton=document.createElement('button');breakerButton.textContent='Sicherungen';breakerButton.title='Hersteller für alle Sicherungen der Dispo';$('autoDispo').after(breakerButton);breakerButton.onclick=()=>{if(current().type!=='dispo'){toast('Bitte zuerst die Dispo-Seite öffnen.');return;}showForm('Sicherungen – für die ganze Dispo',[{key:'manufacturer',label:'Hersteller für alle LS / FI-LS',value:current().dispoConfig?.breakerManufacturer||'auto',options:[['auto','Einzeleinstellungen / Vorlagen'],['hager','Hager – nach L1 / L2 / L3 in drei Reihen'],['schneider','Schneider – nebeneinander']]}],data=>{change(()=>current().dispoConfig={...defaultConfig(),...current().dispoConfig,breakerManufacturer:data.manufacturer});toast('Gespeichert. Mit Dispo erzeugen die Anordnung aktualisieren.');});};

const standardButton=document.createElement('button');standardButton.textContent='Drahtwerk-Standardseiten';$('projectSettings').after(standardButton);standardButton.onclick=()=>{try{const next=addStandardPages(clone(doc));change(()=>doc=next);}catch(error){toast(error.message);}};
